    { id: 11191, theme: "Sciences", d: 2.4, q: "Quels minuscules êtres vivants flottent dans la mer et nourrissent les baleines ?", a: ["Le plancton", "Plancton"], exp: "Le phytoplancton produit une grande partie de notre oxygène." },
    { id: 11192, theme: "Sciences", d: 2.4, q: "Quel animal marin a trois cœurs et du sang bleu ?", a: ["La pieuvre", "Pieuvre", "Poulpe"], exp: "Deux cœurs pour les branchies, un pour le corps." },
    { id: 11193, theme: "Sciences", d: 2.4, q: "Quel sens utilisent les chauves-souris et les dauphins pour « voir » avec des sons ?", a: ["L’écholocation", "Écholocation", "Echolocation", "Sonar"], exp: "Ils écoutent l’écho de leurs cris." },
    { id: 11194, theme: "Sciences", d: 2.5, q: "Quelle classe d’animaux vit dans l’eau puis sur terre, comme la grenouille ?", a: ["Les amphibiens", "Amphibiens", "Amphibien", "Batraciens"], exp: "Du grec « double vie »." },
    { id: 11195, theme: "Sciences", d: 2.5, q: "Comment appelle-t-on la suite « qui mange qui » dans la nature ?", a: ["La chaîne alimentaire", "Chaîne alimentaire"], exp: "Elle commence presque toujours par des plantes." },
    { id: 11196, theme: "Sciences", d: 2.5, q: "Comment appelle-t-on le scientifique qui étudie les fossiles ?", a: ["Un paléontologue", "Paléontologue"], exp: "À ne pas confondre avec l’archéologue, qui étudie les traces humaines." },
    { id: 11197, theme: "Sciences", d: 2.5, q: "Comment appelle-t-on l’ensemble des êtres vivants et de leur milieu, comme une forêt ou une mare ?", a: ["Un écosystème", "Écosystème", "Ecosysteme"], exp: "Tout y est lié : plantes, animaux, sol, climat." },
    { id: 11198, theme: "Sciences", d: 2.6, q: "Comment appelle-t-on la diversité de toutes les espèces vivantes ?", a: ["La biodiversité", "Biodiversité", "Biodiversite"], exp: "On connaît environ 2 millions d’espèces, sans doute une petite partie du total." },
    { id: 11199, theme: "Sciences", d: 2.6, q: "Quels minuscules morceaux de plastique polluent les océans et même notre corps ?", a: ["Les microplastiques", "Microplastiques", "Microplastique"], exp: "Moins de 5 mm." },
    { id: 11200, theme: "Sciences", d: 2.6, q: "Quelle énergie utilise la chaleur du sous-sol, très développée en Islande ?", a: ["La géothermie", "Géothermie", "Geothermie"], exp: "Elle chauffe presque toutes les maisons islandaises." },
    { id: 11201, theme: "Sciences", d: 2.6, q: "Quel gaz fossile, surtout fait de méthane, sert à chauffer et cuisiner ?", a: ["Le gaz naturel", "Gaz naturel", "Méthane"], exp: "On lui ajoute une odeur pour détecter les fuites." },
    { id: 11202, theme: "Sciences", d: 2.7, q: "Quel examen médical utilise un énorme aimant pour voir l’intérieur du corps ?", a: ["L’IRM", "IRM", "Imagerie par résonance magnétique"], exp: "Imagerie par résonance magnétique, sans rayons X." },
    { id: 11205, theme: "Sciences", d: 2.7, q: "Quelle partie liquide et jaunâtre du sang transporte les cellules ?", a: ["Le plasma", "Plasma"], exp: "Plus de la moitié du volume du sang." },
    { id: 11206, theme: "Sciences", d: 2.8, q: "Quelles protéines fabriquées par le corps reconnaissent et neutralisent les microbes ?", a: ["Les anticorps", "Anticorps"], exp: "Les vaccins apprennent au corps à les fabriquer." },
    { id: 11207, theme: "Sciences", d: 2.8, q: "Quel pigment colore la peau et la protège du soleil ?", a: ["La mélanine", "Mélanine", "Melanine"], exp: "Le bronzage, c’est la peau qui en fabrique plus." },
    { id: 11208, theme: "Sciences", d: 2.8, q: "Comment s’appelle la couche la plus externe de la peau ?", a: ["L’épiderme", "Épiderme", "Epiderme"], exp: "Elle se renouvelle environ tous les mois." },
    { id: 11209, theme: "Sciences", d: 2.8, q: "Quel muscle se trouve à l’arrière du bras, opposé au biceps ?", a: ["Le triceps", "Triceps"], exp: "Il sert à tendre le bras." },
    { id: 11210, theme: "Sciences", d: 2.9, q: "Quel groupe de muscles, à l’avant de la cuisse, est le plus puissant du corps ?", a: ["Le quadriceps", "Quadriceps"], exp: "Il compte quatre chefs, d’où son nom." },
    { id: 11211, theme: "Sciences", d: 2.9, q: "Quel os plat du thorax relie les côtes à l’avant ?", a: ["Le sternum", "Sternum"], exp: "On appuie dessus pour un massage cardiaque." },
    { id: 11212, theme: "Sciences", d: 2.9, q: "Quelle partie du cerveau, à l’arrière, gère l’équilibre et la coordination ?", a: ["Le cervelet", "Cervelet"], exp: "Il contient plus de neurones que tout le reste du cerveau." },
    { id: 11213, theme: "Sciences", d: 2.9, q: "Comment s’appelle la cellule nerveuse qui transmet l’information ?", a: ["Le neurone", "Neurone"], exp: "Environ 86 milliards dans le cerveau humain." },
    { id: 11214, theme: "Sciences", d: 3.0, q: "Quel cordon nerveux passe à l’intérieur de la colonne vertébrale ?", a: ["La moelle épinière", "Moelle épinière", "Moelle epiniere"], exp: "À ne pas confondre avec la moelle osseuse, qui fabrique le sang." },
    { id: 11215, theme: "Sciences", d: 3.0, q: "Quel petit tube accroché au gros intestin s’enflamme parfois et doit être opéré ?", a: ["L’appendice", "Appendice"], exp: "L’appendicite est une urgence chirurgicale courante." },
    { id: 11216, theme: "Sciences", d: 3.0, q: "Quelle lentille de l’œil, derrière la pupille, devient opaque avec la cataracte ?", a: ["Le cristallin", "Cristallin"], exp: "On peut le remplacer par une lentille artificielle." },
    { id: 11217, theme: "Sciences", d: 3.0, q: "Quelle partie du cerveau, en forme de cheval de mer, joue un rôle clé dans la mémoire ?", a: ["L’hippocampe", "Hippocampe"], exp: "Son nom vient justement du cheval de mer." },
    { id: 11218, theme: "Sciences", d: 3.1, q: "Pendant quelle phase du sommeil fait-on les rêves les plus vivants ?", a: ["Le sommeil paradoxal", "Sommeil paradoxal", "REM"], exp: "Les yeux bougent vite sous les paupières." },
    { id: 11219, theme: "Sciences", d: 3.1, q: "Comment appelle-t-on notre horloge biologique d’environ 24 heures ?", a: ["Le rythme circadien", "Rythme circadien", "Circadien", "Horloge circadienne"], exp: "Du latin « circa diem », environ un jour." },
    { id: 11220, theme: "Sciences", d: 3.1, q: "Quelle molécule du cerveau, souvent appelée « hormone du bonheur », régule l’humeur ?", a: ["La sérotonine", "Sérotonine", "Serotonine"], exp: "Elle joue aussi un rôle dans le sommeil et l’appétit." },
    { id: 11221, theme: "Sciences", d: 3.1, q: "Quelle maladie des os, due à un manque de vitamine D, touchait les enfants ?", a: ["Le rachitisme", "Rachitisme"], exp: "Les os deviennent mous et se déforment." },
    { id: 11222, theme: "Sciences", d: 2.2, q: "Comment appelle-t-on les sucres, source rapide d’énergie (pâtes, pain, fruits) ?", a: ["Les glucides", "Glucides", "Sucres"], exp: "Avec les lipides et les protéines, l’un des trois grands nutriments." },
    { id: 11223, theme: "Sciences", d: 2.5, q: "Comment appelle-t-on les graisses dans l’alimentation ?", a: ["Les lipides", "Lipides"], exp: "Ils apportent 9 kilocalories par gramme, plus que tout le reste." },
    { id: 11224, theme: "Sciences", d: 2.6, q: "Quelles parties des végétaux, non digérées, aident le transit intestinal ?", a: ["Les fibres", "Fibres", "Fibres alimentaires"], exp: "On en trouve dans les légumes, les fruits et les céréales complètes." },
    { id: 11225, theme: "Sciences", d: 2.4, q: "Quelle graisse du sang, en excès, peut boucher les artères ?", a: ["Le cholestérol", "Cholestérol", "Cholesterol"], exp: "Il y a le « bon » (HDL) et le « mauvais » (LDL)." },
    { id: 11226, theme: "Sciences", d: 1.9, q: "Avec quelle unité mesure-t-on l’énergie apportée par les aliments ?", a: ["La calorie", "Calories", "Kilocalorie", "kcal"], exp: "En réalité, on parle de kilocalories." },
    { id: 11228, theme: "Sciences", d: 3.2, q: "Quels deux scientifiques ont décrit la double hélice de l’ADN en 1953 ?", a: ["Watson et Crick", "James Watson et Francis Crick", "Crick et Watson"], exp: "Grâce aux images de Rosalind Franklin." },
    { id: 11229, theme: "Sciences", d: 3.2, q: "Quel procédé de Pasteur chauffe un liquide pour tuer les microbes sans le bouillir ?", a: ["La pasteurisation", "Pasteurisation"], exp: "Inventé d’abord pour le vin, puis pour le lait." },
    { id: 11230, theme: "Sciences", d: 3.2, q: "Quel élément radioactif, brillant dans le noir, Marie et Pierre Curie ont-ils découvert en 1898 avec le polonium ?", a: ["Le radium", "Radium"], exp: "On en mettait sur les aiguilles des montres… dangereusement." },
    { id: 11231, theme: "Sciences", d: 3.3, q: "Quel physicien, mari de Marie Curie, est mort renversé par une voiture à cheval en 1906 ?", a: ["Pierre Curie"], exp: "Prix Nobel de physique 1903 avec Marie et Henri Becquerel." },
    { id: 11232, theme: "Sciences", d: 2.8, q: "Quelle est la formule la plus célèbre d’Einstein ?", a: ["E = mc²", "E=mc2", "E=mc²", "E = mc2"], exp: "L’énergie égale la masse fois la vitesse de la lumière au carré." },
    { id: 11233, theme: "Sciences", d: 3.3, q: "Comment s’appelle la théorie qui place le Soleil au centre du système solaire ?", a: ["L’héliocentrisme", "Héliocentrisme", "Heliocentrisme"], exp: "Défendue par Copernic en 1543." },
    { id: 11234, theme: "Sciences", d: 3.0, q: "Quelle force pousse vers le haut un objet plongé dans un liquide ?", a: ["La poussée d’Archimède", "Poussée d’Archimède", "Archimède"], exp: "C’est elle qui fait flotter les bateaux." },
    { id: 11235, theme: "Sciences", d: 3.3, q: "Quel savant grec a donné son nom à un théorème sur les droites parallèles dans un triangle ?", a: ["Thalès", "Thales"], exp: "Il aurait mesuré la hauteur des pyramides grâce à leur ombre." },
    { id: 11237, theme: "Sciences", d: 3.4, q: "Quel gaz noble représente environ 1 % de l’air que nous respirons ?", a: ["L’argon", "Argon"], exp: "Après l’azote (78 %) et l’oxygène (21 %)." },
    { id: 11238, theme: "Sciences", d: 3.4, q: "Quel élément radioactif porte le nom de la planète naine la plus célèbre ?", a: ["Le plutonium", "Plutonium"], exp: "Comme l’uranium et le neptunium, du nom de planètes." },
    { id: 11239, theme: "Sciences", d: 3.4, q: "Quel élément de symbole K trouve-t-on beaucoup dans la banane ?", a: ["Le potassium", "Potassium"], exp: "K vient du latin « kalium »." },
    { id: 11240, theme: "Sciences", d: 3.5, q: "Quel gaz jaune-vert sert à désinfecter l’eau des piscines ?", a: ["Le chlore", "Chlore"], exp: "Symbole Cl." },
    { id: 11241, theme: "Sciences", d: 3.5, q: "Quel élément, abondant dans les algues, est indispensable à la thyroïde ?", a: ["L’iode", "Iode"], exp: "On en ajoute au sel de cuisine." },
    { id: 11242, theme: "Sciences", d: 3.5, q: "Quel élément ajouté au dentifrice protège les dents des caries ?", a: ["Le fluor", "Fluor"], exp: "Symbole F." },
    { id: 11243, theme: "Sciences", d: 3.5, q: "Quelle forme de carbone, très tendre, fait la mine des crayons ?", a: ["Le graphite", "Graphite"], exp: "Le diamant est aussi du carbone pur." },
    { id: 11244, theme: "Sciences", d: 3.6, q: "Comment appelle-t-on le passage direct de l’état solide à l’état gazeux ?", a: ["La sublimation", "Sublimation"], exp: "La glace carbonique fait ça : elle « fume » sans fondre." },
    { id: 11245, theme: "Sciences", d: 3.6, q: "Comment appelle-t-on le passage de la vapeur à l’état liquide, comme la buée ?", a: ["La condensation", "Condensation"], exp: "Le contraire de l’évaporation." },
    { id: 11246, theme: "Sciences", d: 3.6, q: "Comment appelle-t-on la cassure d’un noyau d’atome lourd, utilisée dans les centrales ?", a: ["La fission", "Fission", "Fission nucléaire"], exp: "Le Soleil, lui, fonctionne par fusion." },
    { id: 11247, theme: "Sciences", d: 3.6, q: "Comment appelle-t-on la réaction chimique de la rouille, quand un métal réagit avec l’oxygène ?", a: ["L’oxydation", "Oxydation"], exp: "Une pomme coupée qui brunit, c’est aussi une oxydation." },
    { id: 11248, theme: "Sciences", d: 3.7, q: "En quelle unité mesure-t-on la résistance électrique ?", a: ["L’ohm", "Ohm", "Ohms"], exp: "Symbole Ω, du physicien allemand Georg Ohm." },
    { id: 11249, theme: "Sciences", d: 3.7, q: "En quelle unité mesure-t-on une force, du nom d’un savant anglais ?", a: ["Le newton", "Newton"], exp: "Environ le poids d’une petite pomme." },
    { id: 11251, theme: "Sciences", d: 3.8, q: "Quel pilote américain a franchi le premier le mur du son, en 1947 ?", a: ["Chuck Yeager", "Yeager"], exp: "À bord de l’avion-fusée Bell X-1." },
    { id: 11252, theme: "Sciences", d: 3.8, q: "Quel chirurgien sud-africain a réussi la première greffe du cœur, en 1967 ?", a: ["Christiaan Barnard", "Barnard"], exp: "Au Cap ; le patient a survécu 18 jours." },
    { id: 11253, theme: "Sciences", d: 3.8, q: "Quelle échelle de température place l’eau qui gèle à 32 degrés ?", a: ["Fahrenheit", "L’échelle Fahrenheit"], exp: "Toujours utilisée aux États-Unis." },
    { id: 11254, theme: "Sciences", d: 3.9, q: "Quel oiseau-dinosaure à plumes de 150 millions d’années a été trouvé en Allemagne ?", a: ["L’archéoptéryx", "Archéoptéryx", "Archaeopteryx"], exp: "Le chaînon entre dinosaures et oiseaux." },
    { id: 11255, theme: "Sciences", d: 3.9, q: "Quel organisme est une association d’un champignon et d’une algue, sur les rochers et les arbres ?", a: ["Le lichen", "Lichen", "Lichens"], exp: "Très sensible à la pollution de l’air." },
    { id: 11256, theme: "Sciences", d: 3.9, q: "Quelle classe de mollusques regroupe pieuvres, calmars et seiches ?", a: ["Les céphalopodes", "Céphalopodes", "Cephalopodes"], exp: "« Céphalopode » veut dire « tête-pieds »." },
    { id: 11257, theme: "Sciences", d: 4.0, q: "Quelle partie mâle de la fleur produit le pollen ?", a: ["L’étamine", "Étamine", "Etamine", "Étamines"], exp: "La partie femelle est le pistil." },
    { id: 11258, theme: "Sciences", d: 4.0, q: "Comment s’appelle la partie femelle de la fleur, au centre ?", a: ["Le pistil", "Pistil"], exp: "Il contient l’ovaire, qui deviendra le fruit." },
    { id: 11259, theme: "Sciences", d: 4.0, q: "Comment appelle-t-on un nuage de gaz et de poussières dans l’espace, où naissent des étoiles ?", a: ["Une nébuleuse", "Nébuleuse", "Nebuleuse"], exp: "La nébuleuse d’Orion est visible à l’œil nu." },
    { id: 11260, theme: "Sciences", d: 4.1, q: "Quel instrument mesure l’humidité de l’air ?", a: ["L’hygromètre", "Hygromètre", "Hygrometre"], exp: "Certains utilisent… un cheveu, qui s’allonge à l’humidité." },
    { id: 11261, theme: "Sciences", d: 4.1, q: "Quel os mobile du crâne permet de mâcher ?", a: ["La mâchoire inférieure", "Mandibule", "Mâchoire"], exp: "La mandibule est le seul os mobile de la tête." },
    { id: 11262, theme: "Sciences", d: 2.0, q: "Comment s’appellent les petits os empilés qui forment la colonne vertébrale ?", a: ["Les vertèbres", "Vertèbres", "Vertèbre"], exp: "33 en tout, dont 24 mobiles." },
    { id: 11263, theme: "Sciences", d: 2.3, q: "Quels minuscules vaisseaux sanguins relient artères et veines ?", a: ["Les capillaires", "Capillaires"], exp: "Plus fins qu’un cheveu, d’où leur nom." },
    { id: 11264, theme: "Sciences", d: 1.6, q: "Quel liquide acide l’estomac produit-il pour digérer ?", a: ["Le suc gastrique", "Suc gastrique", "Acide gastrique"], exp: "Il contient de l’acide chlorhydrique." },
    { id: 11265, theme: "Sciences", d: 2.7, q: "Comment appelle-t-on les énergies qui ne s’épuisent pas, comme le vent ou le soleil ?", a: ["Les énergies renouvelables", "Énergies renouvelables", "Renouvelables"], exp: "Le contraire des énergies fossiles." },
    { id: 11266, theme: "Sciences", d: 2.9, q: "Quel est le plus grand barrage hydroélectrique du monde, en Chine ?", a: ["Le barrage des Trois-Gorges", "Trois-Gorges", "Trois Gorges"], exp: "Sur le Yangzi, mis en service en 2012." },
    { id: 11267, theme: "Sciences", d: 3.0, q: "Comment appelle-t-on la disparition définitive d’une espèce ?", a: ["L’extinction", "Extinction"], exp: "Les dinosaures non aviens ont disparu il y a 66 millions d’années." },
    { id: 11268, theme: "Sciences", d: 2.2, q: "Comment appelle-t-on un véhicule robot qui roule sur une autre planète ?", a: ["Un rover", "Rover", "Astromobile"], exp: "En français : astromobile." },
    { id: 11269, theme: "Sciences", d: 3.3, q: "Pourquoi la Lune semble-t-elle changer de forme au fil du mois ?", a: ["Les phases de la Lune", "Phases", "Phases de la Lune"], exp: "On voit une partie plus ou moins grande de sa face éclairée : un cycle de 29,5 jours." },
    { id: 11270, theme: "Sciences", d: 3.1, q: "Quel examen médical en tranches utilise des rayons X tournant autour du patient ?", a: ["Le scanner", "Scanner", "Tomodensitométrie"], exp: "Inventé en 1972 par Godfrey Hounsfield." },
    { id: 11271, theme: "Sciences", d: 1.1, q: "Comment appelle-t-on la fine couche de glace blanche qui couvre l’herbe les matins froids ?", a: ["Le givre", "Givre", "Gelée blanche"], exp: "La vapeur d’eau gèle directement au contact du froid." },
    { id: 11272, theme: "Sciences", d: 1.2, q: "Quel grand nuage sombre en forme d’enclume apporte les orages ?", a: ["Le cumulonimbus", "Cumulonimbus"], exp: "Il peut monter à plus de 10 km d’altitude." },
    { id: 11273, theme: "Sciences", d: 1.2, q: "Quels voiles lumineux colorés dansent dans le ciel près des pôles ?", a: ["Les aurores boréales", "Aurore boréale", "Aurores polaires", "Aurore polaire"], exp: "Au pôle Sud, on parle d’aurores australes." },
    { id: 11274, theme: "Sciences", d: 1.3, q: "Quel organe de la gorge contient les cordes vocales ?", a: ["Le larynx", "Larynx"], exp: "La « pomme d’Adam » en est la partie visible." },
    { id: 11275, theme: "Sciences", d: 1.3, q: "Quel tuyau conduit l’air de la gorge jusqu’aux poumons ?", a: ["La trachée", "Trachée", "Trachee"], exp: "Elle se divise ensuite en deux bronches." },
    { id: 11276, theme: "Sciences", d: 1.4, q: "Quelle petite masse de chair pend au fond de la gorge ?", a: ["La luette", "Luette"], exp: "Elle aide à fermer le nez quand on avale." },
    { id: 11277, theme: "Sciences", d: 1.4, q: "Comment appelle-t-on la couche dure qui recouvre les dents ?", a: ["L’émail", "Émail", "Email"], exp: "La matière la plus dure du corps humain." },
    { id: 11278, theme: "Sciences", d: 1.4, q: "Comment appelle-t-on le trou dans une dent causé par les bactéries et le sucre ?", a: ["Une carie", "Carie", "Caries"], exp: "Le brossage et le fluor la préviennent." },
    { id: 11279, theme: "Sciences", d: 1.5, q: "Quelle maladie d’enfance donne des boutons qui démangent et des croûtes ?", a: ["La varicelle", "Varicelle"], exp: "On ne l’attrape en général qu’une fois." },
    { id: 11280, theme: "Sciences", d: 1.5, q: "Comment appelle-t-on la marque bleue qui apparaît après un coup ?", a: ["Un bleu", "Bleu", "Ecchymose", "Hématome"], exp: "Elle passe ensuite au vert puis au jaune." },
    { id: 11281, theme: "Sciences", d: 1.5, q: "Comment appelle-t-on une cheville tordue dont les ligaments sont étirés ?", a: ["Une entorse", "Entorse", "Foulure"], exp: "Une foulure est une entorse légère." },
    { id: 11282, theme: "Sciences", d: 1.6, q: "Quelle infection de l’oreille fait souvent mal aux enfants ?", a: ["Une otite", "Otite"], exp: "Du grec « ous, otos », l’oreille." },
    { id: 11283, theme: "Sciences", d: 1.6, q: "Comment appelle-t-on une personne qui marche en dormant ?", a: ["Un somnambule", "Somnambule", "Somnambulisme"], exp: "Il ne faut pas le réveiller brusquement." },
    { id: 11284, theme: "Sciences", d: 1.6, q: "Combien de mois dure une grossesse humaine environ ?", a: ["9", "Neuf", "9 mois"], exp: "Environ 40 semaines." },
    { id: 11285, theme: "Sciences", d: 1.7, q: "Quel cordon relie le bébé à sa mère pendant la grossesse ?", a: ["Le cordon ombilical", "Cordon ombilical"], exp: "Le nombril en est la cicatrice." },
    { id: 11286, theme: "Sciences", d: 1.7, q: "Comment appelle-t-on des jumeaux issus d’un même œuf, avec le même ADN ?", a: ["De vrais jumeaux", "Vrais jumeaux", "Jumeaux monozygotes"], exp: "Leurs empreintes digitales sont pourtant différentes." },
    { id: 11287, theme: "Sciences", d: 1.7, q: "Comment appelle-t-on le changement de peau du serpent ?", a: ["La mue", "Mue"], exp: "Il en sort comme d’une chaussette retournée." },
    { id: 11288, theme: "Sciences", d: 1.8, q: "Quel grand nid de terre construisent certains insectes d’Afrique, parfois haut de plusieurs mètres ?", a: ["Une termitière", "Termitière", "Termitiere"], exp: "Elle est climatisée naturellement par des conduits d’air." },
    { id: 11289, theme: "Sciences", d: 1.8, q: "Quelle couleur a la peau de l’ours polaire, sous sa fourrure ?", a: ["Noire", "Noir"], exp: "Pour capter la chaleur du soleil ; ses poils sont transparents." },
    { id: 11290, theme: "Sciences", d: 1.8, q: "Quel est le plus grand poisson du monde, un requin mangeur de plancton ?", a: ["Le requin-baleine", "Requin-baleine", "Requin baleine"], exp: "Jusqu’à 18 m, inoffensif pour l’homme." },
    { id: 11291, theme: "Sciences", d: 1.9, q: "Quelle plante carnivore referme ses feuilles comme une mâchoire sur les insectes ?", a: ["La dionée", "Dionée", "Dionee", "Attrape-mouche"], exp: "Il faut toucher deux fois ses poils pour la déclencher." },
    { id: 11292, theme: "Sciences", d: 1.9, q: "Quel arbre africain au tronc énorme stocke de l’eau et vit plus de 1 000 ans ?", a: ["Le baobab", "Baobab"], exp: "Le Petit Prince en arrachait les pousses sur sa planète." },
    { id: 11293, theme: "Sciences", d: 2.0, q: "Comment appelle-t-on le moment où une graine commence à pousser ?", a: ["La germination", "Germination"], exp: "Il lui faut de l’eau, de l’air et de la chaleur." },
    { id: 11294, theme: "Sciences", d: 2.0, q: "Quelle planète, très brillante au crépuscule, est surnommée « l’étoile du Berger » ?", a: ["Vénus", "Venus"], exp: "Ce n’est pas une étoile : elle reflète la lumière du Soleil." },
    { id: 11295, theme: "Sciences", d: 2.1, q: "De quoi sont faits surtout les anneaux de Saturne ?", a: ["De glace", "Glace", "Glace et roche", "Glace et poussière"], exp: "Des morceaux de la taille d’un grain de sable à celle d’une maison." },
    { id: 11296, theme: "Sciences", d: 2.2, q: "Quelle immense tempête, plus grande que la Terre, tourne sur Jupiter depuis près de deux siècles ?", a: ["La Grande Tache rouge", "Grande Tache rouge", "Tache rouge"], exp: "Observée depuis au moins 1830." },
    { id: 11297, theme: "Sciences", d: 2.3, q: "Quelle constellation contient l’étoile polaire ?", a: ["La Petite Ourse", "Petite Ourse"], exp: "L’étoile polaire est au bout de sa « queue »." },
    { id: 11298, theme: "Sciences", d: 2.4, q: "Quel vaisseau spatial américain, réutilisable, a volé de 1981 à 2011 ?", a: ["La navette spatiale", "Navette spatiale", "Space Shuttle"], exp: "Cinq navettes, dont Challenger et Columbia, détruites en vol." },
    { id: 11299, theme: "Sciences", d: 2.5, q: "Quelle substance des pommes de terre et du riz devient bleue au contact de l’iode ?", a: ["L’amidon", "Amidon"], exp: "Une expérience classique en classe de SVT." },
    { id: 11300, theme: "Sciences", d: 2.6, q: "Comment appelle-t-on les battements du cœur qu’on sent au poignet ?", a: ["Le pouls", "Pouls"], exp: "Entre 60 et 100 battements par minute au repos." },
    { id: 11301, theme: "Sciences", d: 2.7, q: "Quelle protéine forme les ongles et les cheveux ?", a: ["La kératine", "Kératine", "Keratine"], exp: "On la retrouve aussi dans les cornes et les plumes." },
    { id: 11302, theme: "Sciences", d: 2.8, q: "Quel système d’unités, né pendant la Révolution française, utilise le mètre et le kilogramme ?", a: ["Le système métrique", "Système métrique", "Système international"], exp: "Adopté aujourd’hui presque partout, sauf aux États-Unis." },
    { id: 11303, theme: "Sciences", d: 3.0, q: "Comment s’appelle la plus grande lune de Mars, qui s’en rapproche peu à peu ?", a: ["Phobos"], exp: "Elle devrait s’écraser sur Mars ou se briser dans environ 50 millions d’années." },
    { id: 11304, theme: "Sciences", d: 3.2, q: "Quels petits nuages blancs, fins comme des cheveux, sont les plus hauts du ciel ?", a: ["Les cirrus", "Cirrus"], exp: "Ils sont faits de cristaux de glace." },
    { id: 11305, theme: "Sciences", d: 3.4, q: "Comment appelle-t-on la température à laquelle un solide devient liquide ?", a: ["Le point de fusion", "Point de fusion", "Température de fusion"], exp: "0 °C pour la glace, 1 538 °C pour le fer." }
